// Turn Settings into the input for the Google Trends Scraper
const s = $json;
const terms = String(s.seedKeywords || '')
  .split(',')
  .map(t => t.trim())
  .filter(Boolean);
if (!terms.length) throw new Error('Add at least one seed keyword in Settings');

return [{
  json: {
    actorInput: {
      searchTerms: terms,
      comparisonMode: 'separate',
      geo: s.country || '',
      timeRange: s.timeRange || 'today 3-m',
      interestOverTime: false,
      relatedQueries: true,
      maxRelatedItems: 25,
    },
  },
}];

// Collect rising searches (and strong top searches) for every seed keyword
const settings = $('Settings').first().json;
const seeds = new Set(
  String(settings.seedKeywords || '').split(',').map(t => t.trim().toLowerCase()).filter(Boolean)
);
const maxIdeas = Number(settings.maxIdeas) || 10;
const onlyRelated = settings.onlyRelatedToSeed !== false;
const ideas = new Map();
// Google Trends also lists unrelated searches (for example "how to cook pasta" for "ai agents").
// Keep a query only if it shares a real word with its seed keyword.
const words = t => String(t).toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(w => w.length > 2);
const isRelated = (query, seed) => {
  const seedWords = words(seed);
  const queryWords = new Set(words(query));
  if (!seedWords.length) return true;
  return seedWords.some(w => queryWords.has(w) || [...queryWords].some(q => q.startsWith(w) || (w.startsWith(q) && q.length >= w.length - 2)));
};

for (const { json: item } of $input.all()) {
  if (item.type !== 'term' || item.status !== 'ok') continue;
  const lists = [
    ['rising', item.relatedQueriesRising || []],
    ['top', item.relatedQueriesTop || []],
  ];
  for (const [list, rows] of lists) {
    for (const q of rows) {
      const query = String(q.query || '').trim();
      const key = query.toLowerCase();
      if (!query || seeds.has(key)) continue;
      if (onlyRelated && !isRelated(query, item.term)) continue;
      // Breakout = growth over 5000%; rising values are % growth, top values are 0-100
      const score = list === 'rising'
        ? (q.isBreakout ? 100000 : Number(q.value) || 0)
        : (Number(q.value) || 0) / 10;
      const prev = ideas.get(key);
      if (prev && prev.score >= score) continue;
      ideas.set(key, {
        key,
        query,
        seedKeyword: item.term,
        trend: list === 'rising' ? (q.formattedValue || String(q.value)) : 'Top search',
        score,
        country: item.geo,
        trendsLink: q.link || '',
        relatedTop: (item.relatedQueriesTop || []).slice(0, 5).map(r => r.query).join(', '),
      });
    }
  }
}

const sorted = [...ideas.values()].sort((a, b) => b.score - a.score);
// Keep extra candidates, the next step removes ideas you already have
return sorted.slice(0, maxIdeas * 3).map(json => ({ json }));

// Skip ideas that are already in the sheet and keep the best N
const saved = new Set(
  $input.all()
    .map(i => String(i.json.query || '').trim().toLowerCase())
    .filter(Boolean)
);
const maxIdeas = Number($('Settings').first().json.maxIdeas) || 10;

return $('Pick rising queries').all()
  .filter(i => !saved.has(i.json.key))
  .slice(0, maxIdeas)
  .map(i => ({ json: i.json }));

