// One flat row per idea for Google Sheets
const ideas = $('Keep only new ideas').all();
return $input.all().map((item, i) => {
  const idea = ideas[i].json;
  const b = item.json.output || {};
  return {
    json: {
      date: new Date().toISOString().slice(0, 10),
      query: idea.query,
      seedKeyword: idea.seedKeyword,
      trend: idea.trend,
      priority: b.priority || '',
      searchIntent: b.searchIntent || '',
      contentType: b.contentType || '',
      title: b.title || '',
      outline: (b.outline || []).join(' | '),
      targetKeywords: (b.targetKeywords || []).join(', '),
      whyNow: b.whyNow || '',
      trendsLink: idea.trendsLink,
    },
  };
});
